diff --git a/mail/metrics.yaml b/mail/metrics.yaml
index 0c5477ddba5..4402c101d6c 100644
--- a/mail/metrics.yaml
+++ b/mail/metrics.yaml
@@ -320,3 +320,45 @@ mail:
       - Virtual
       - Other
       - Total
+
+  compact_result:
+    type: labeled_counter
+    description: >
+      Counts the number of folder compactions that happen and how they ended.
+    bugs:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1926152
+    data_reviews:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1926152#cX
+    notification_emails:
+      - telemetry-client-dev@thunderbird.net
+    expires: never
+
+  compact_duration:
+    type: timing_distribution
+    time_unit: millisecond
+    description: >
+      Counts how long each folder compaction takes.
+    bugs:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1926152
+    data_reviews:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1926152#cX
+    notification_emails:
+      - telemetry-client-dev@thunderbird.net
+    expires: never
+
+  compact_bytes_recovered:
+    type: custom_distribution
+    description: >
+      Number of bytes recovered by compaction.
+    range_min: 1
+    range_max: 1073741824 # 1GiB
+    bucket_count: 50
+    histogram_type: exponential
+    unit: bytes
+    bugs:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1926152
+    data_reviews:
+      - https://bugzilla.mozilla.org/show_bug.cgi?id=1926152#cX
+    notification_emails:
+      - telemetry-client-dev@thunderbird.net
+    expires: never
diff --git a/mailnews/base/src/FolderCompactor.cpp b/mailnews/base/src/FolderCompactor.cpp
index a5dbeb1ea3c..13fa21e2cdb 100644
--- a/mailnews/base/src/FolderCompactor.cpp
+++ b/mailnews/base/src/FolderCompactor.cpp
@@ -31,6 +31,7 @@
 #include "mozilla/RefCounted.h"
 #include "mozilla/Services.h"
 #include "mozilla/ScopeExit.h"
+#include "mozilla/glean/GleanMetrics.h"

 mozilla::LazyLogModule gCompactLog("compact");
 using mozilla::LogLevel;
@@ -110,6 +111,9 @@ class FolderCompactor : public nsIStoreCompactListener {

   // Running total of kept messages (for progress feedback).
   uint32_t mNumKept{0};
+
+  // Glean timer.
+  uint64_t mTimerId{0};
 };

 NS_IMPL_ISUPPORTS(FolderCompactor, nsIStoreCompactListener)
@@ -372,6 +376,7 @@ NS_IMETHODIMP FolderCompactor::OnCompactionBegin() {
   }

   MOZ_LOG(gCompactLog, LogLevel::Verbose, ("OnCompactionBegin()"));
+  mTimerId = mozilla::glean::mail::compact_duration.Start();
   return NS_OK;
 }

@@ -494,6 +499,13 @@ NS_IMETHODIMP FolderCompactor::OnCompactionComplete(nsresult status,
            " newSize=%" PRId64 ")",
            (uint32_t)status, oldSize, newSize));

+  nsPrintfCString statusStr("%x", (uint32_t)status);
+  mozilla::glean::mail::compact_result.Get(statusStr).Add(1);
+  if (mTimerId) {
+    mozilla::glean::mail::compact_duration.StopAndAccumulate(
+        std::move(mTimerId));
+  }
+
   if (NS_SUCCEEDED(status)) {
     // Commit all the changes.
     nsresult rv = mDB->Commit(nsMsgDBCommitType::kCompressCommit);
@@ -509,6 +521,8 @@ NS_IMETHODIMP FolderCompactor::OnCompactionComplete(nsresult status,
         dbFolderInfo->SetExpungedBytes(0);
       }
       mDB->SetSummaryValid(true);
+      mozilla::glean::mail::compact_bytes_recovered.AccumulateSingleSample(
+          oldSize - newSize);
     } else {
       NS_ERROR("Failed to commit changes to DB!");
       status = rv;  // Make sure our completion fn hears about the failure.
